-- ---------------------------------------------------------------------------
-- Seed catalog: PCI DSS v4.0 and HIPAA.
--
-- WHY. Two new compliance frameworks are added to the platform and their real,
-- published control catalogs are seeded into public.framework_controls so the
-- Frameworks page has an actual catalog behind each framework card (not just a
-- control_count number with nothing behind it).
--
--   * PCI DSS v4.0 — Payment Card Industry Data Security Standard, Requirements
--     and Testing Procedures v4.0 (PCI Security Standards Council, March 2022).
--     All 12 requirements and their real defined-approach sub-requirements.
--   * HIPAA — the HIPAA Security Rule safeguards (45 CFR Part 164, Subpart C,
--     §§164.302-164.318) with their real implementation specifications and the
--     Required (R) / Addressable (A) designation, plus the key Privacy Rule
--     (45 CFR Part 164, Subpart E) and Breach Notification Rule (Subpart D)
--     provisions.
--
-- Every control_ref and title below is the REAL published identifier/title from
-- the actual standard — none are invented. Where a specific ref was uncertain it
-- was omitted rather than guessed (First principle #5: no invented data).
--
-- The `frameworks` row for each is INSERTed first, then its catalog references
-- it. id = 'fc-<framework_id>-<slug(control_ref)>' (slug: lowercase, every run of
-- non-alphanumerics -> '-', trimmed) computed in SQL so rows are deterministic
-- and idempotent. org_id is the demo org. Idempotent; safe to re-run.
-- ---------------------------------------------------------------------------

-- ==========================================================================
-- 1. Framework metadata rows (global; frameworks has no org_id).
-- ==========================================================================
-- org_id: frameworks are global metadata. The live schema has since added a
-- not-null org_id (default get_org_id(), NULL under the migration role), so it
-- must be set explicitly. All existing framework rows live under the
-- __SENTINEL_DEFAULT__ org (all-zero uuid) as the shared/global bucket; these
-- two match that pattern. (Catalog rows in framework_controls stay on the demo
-- org 000...001 per the seed contract.)
INSERT INTO public.frameworks
  (id, org_id, name, short_name, version, category, issuing_body, jurisdiction,
   effective_date, control_count, structure, description, url, adopted, coverage_pct)
VALUES
  ('pci-dss', '00000000-0000-0000-0000-000000000000',
   'Payment Card Industry Data Security Standard', 'PCI DSS', '4.0',
   'Payment Security', 'PCI Security Standards Council', 'Global',
   '2022-03-31', 0, 'requirement',
   'Baseline of technical and operational requirements to protect account data. '
   'Twelve principal requirements grouped into six control objectives, each with '
   'defined-approach sub-requirements and testing procedures.',
   'https://www.pcisecuritystandards.org/', true, 0),
  ('hipaa', '00000000-0000-0000-0000-000000000000',
   'Health Insurance Portability and Accountability Act', 'HIPAA', '2013 Omnibus',
   'Healthcare Privacy', 'U.S. Department of Health and Human Services (HHS)', 'United States',
   '2013-03-26', 0, 'citation',
   'U.S. federal rules protecting the privacy and security of protected health '
   'information (PHI). Covers the Security Rule safeguards (45 CFR 164 Subpart C), '
   'Privacy Rule (Subpart E) and Breach Notification Rule (Subpart D).',
   'https://www.hhs.gov/hipaa/', true, 0)
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, short_name = EXCLUDED.short_name, version = EXCLUDED.version,
  category = EXCLUDED.category, issuing_body = EXCLUDED.issuing_body,
  jurisdiction = EXCLUDED.jurisdiction, effective_date = EXCLUDED.effective_date,
  structure = EXCLUDED.structure, description = EXCLUDED.description,
  url = EXCLUDED.url, adopted = EXCLUDED.adopted;

-- ==========================================================================
-- 2. PCI DSS v4.0 catalog.
-- ==========================================================================
INSERT INTO public.framework_controls
  (id, org_id, framework_id, control_ref, domain, title, description, control_type, priority)
SELECT
  'fc-' || v.framework_id || '-' ||
    regexp_replace(regexp_replace(lower(v.control_ref), '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g'),
  '00000000-0000-0000-0000-000000000001',
  v.framework_id, v.control_ref, v.domain, v.title, v.description, v.control_type, v.priority
FROM (VALUES
  -- Requirement 1: Install and Maintain Network Security Controls
  ('pci-dss','1.1.1','Requirement 1: Install and Maintain Network Security Controls','Security policies and procedures for Requirement 1 are documented','All security policies and operational procedures that are identified in Requirement 1 are documented, kept up to date, in use, and known to all affected parties.','governance','medium'),
  ('pci-dss','1.1.2','Requirement 1: Install and Maintain Network Security Controls','Roles and responsibilities for Requirement 1 are assigned','Roles and responsibilities for performing activities in Requirement 1 are documented, assigned, and understood.','governance','medium'),
  ('pci-dss','1.2.1','Requirement 1: Install and Maintain Network Security Controls','Configuration standards for NSC rulesets','Configuration standards for network security control (NSC) rulesets are defined, implemented, and maintained.','preventive','high'),
  ('pci-dss','1.2.2','Requirement 1: Install and Maintain Network Security Controls','Changes to NSC configurations are managed','All changes to network connections and to configurations of NSCs are approved and managed in accordance with the change control process defined at Requirement 6.5.1.','preventive','high'),
  ('pci-dss','1.2.3','Requirement 1: Install and Maintain Network Security Controls','Network diagram is maintained','An accurate network diagram(s) is maintained that shows all connections between the cardholder data environment (CDE) and other networks, including any wireless networks.','preventive','medium'),
  ('pci-dss','1.2.4','Requirement 1: Install and Maintain Network Security Controls','Data-flow diagram is maintained','An accurate data-flow diagram(s) is maintained that shows all account data flows across systems and networks.','preventive','medium'),
  ('pci-dss','1.2.5','Requirement 1: Install and Maintain Network Security Controls','Services, protocols, and ports are identified and approved','All services, protocols, and ports allowed are identified, approved, and have a defined business need.','preventive','high'),
  ('pci-dss','1.2.6','Requirement 1: Install and Maintain Network Security Controls','Security features for insecure services','Security features are defined and implemented for all services, protocols, and ports that are in use and considered to be insecure, such that the risk is mitigated.','preventive','high'),
  ('pci-dss','1.2.7','Requirement 1: Install and Maintain Network Security Controls','NSC configurations are reviewed periodically','Configurations of NSCs are reviewed at least once every six months to confirm they are relevant and effective.','detective','medium'),
  ('pci-dss','1.2.8','Requirement 1: Install and Maintain Network Security Controls','NSC configuration files are secured','Configuration files for NSCs are secured from unauthorized access and kept consistent with active network configurations.','preventive','high'),
  ('pci-dss','1.3.1','Requirement 1: Install and Maintain Network Security Controls','Inbound traffic to the CDE is restricted','Inbound traffic to the CDE is restricted to only traffic that is necessary; all other traffic is specifically denied.','preventive','high'),
  ('pci-dss','1.3.2','Requirement 1: Install and Maintain Network Security Controls','Outbound traffic from the CDE is restricted','Outbound traffic from the CDE is restricted to only traffic that is necessary; all other traffic is specifically denied.','preventive','high'),
  ('pci-dss','1.3.3','Requirement 1: Install and Maintain Network Security Controls','NSCs between wireless networks and the CDE','NSCs are installed between all wireless networks and the CDE, regardless of whether the wireless network is a CDE, such that only authorized traffic is permitted.','preventive','high'),
  ('pci-dss','1.4.1','Requirement 1: Install and Maintain Network Security Controls','NSCs between trusted and untrusted networks','NSCs are implemented between trusted and untrusted networks.','preventive','high'),
  ('pci-dss','1.4.2','Requirement 1: Install and Maintain Network Security Controls','Inbound traffic from untrusted networks is restricted','Inbound traffic from untrusted networks to trusted networks is restricted to communications with authorized system components and stateful responses.','preventive','high'),
  ('pci-dss','1.4.3','Requirement 1: Install and Maintain Network Security Controls','Anti-spoofing measures','Anti-spoofing measures are implemented to detect and block forged source IP addresses from entering the trusted network.','preventive','medium'),
  ('pci-dss','1.4.4','Requirement 1: Install and Maintain Network Security Controls','Stored account data not accessible from untrusted networks','System components that store cardholder data are not directly accessible from untrusted networks.','preventive','high'),
  ('pci-dss','1.4.5','Requirement 1: Install and Maintain Network Security Controls','Disclosure of internal IP addresses is limited','The disclosure of internal IP addresses and routing information is limited to only authorized parties.','preventive','medium'),
  ('pci-dss','1.5.1','Requirement 1: Install and Maintain Network Security Controls','Controls on devices connecting to both untrusted networks and the CDE','Security controls are implemented on any computing devices, including company- and employee-owned devices, that connect to both untrusted networks and the CDE.','preventive','high'),

  -- Requirement 2: Apply Secure Configurations to All System Components
  ('pci-dss','2.1.1','Requirement 2: Apply Secure Configurations to All System Components','Security policies and procedures for Requirement 2 are documented','All security policies and operational procedures that are identified in Requirement 2 are documented, kept up to date, in use, and known to all affected parties.','governance','medium'),
  ('pci-dss','2.1.2','Requirement 2: Apply Secure Configurations to All System Components','Roles and responsibilities for Requirement 2 are assigned','Roles and responsibilities for performing activities in Requirement 2 are documented, assigned, and understood.','governance','medium'),
  ('pci-dss','2.2.1','Requirement 2: Apply Secure Configurations to All System Components','Configuration standards are developed and maintained','Configuration standards are developed, implemented, and maintained to cover all system components and address all known security vulnerabilities and industry-accepted hardening.','preventive','high'),
  ('pci-dss','2.2.2','Requirement 2: Apply Secure Configurations to All System Components','Vendor default accounts are managed','Vendor default accounts are managed by changing default passwords or removing/disabling the account if not used, before or upon installing a system component.','preventive','high'),
  ('pci-dss','2.2.3','Requirement 2: Apply Secure Configurations to All System Components','Primary functions with different security levels are managed','Primary functions requiring different security levels are managed by isolating them, or by using access controls or hardening techniques to prevent lower-security functions affecting higher-security ones.','preventive','medium'),
  ('pci-dss','2.2.4','Requirement 2: Apply Secure Configurations to All System Components','Only necessary services and functions are enabled','Only necessary services, protocols, daemons, and functions are enabled, and all unnecessary functionality is removed or disabled.','preventive','high'),
  ('pci-dss','2.2.5','Requirement 2: Apply Secure Configurations to All System Components','Insecure services, protocols, or daemons are justified','If any insecure services, protocols, or daemons are present, business justification is documented and additional security features are documented and implemented to reduce the risk.','preventive','medium'),
  ('pci-dss','2.2.6','Requirement 2: Apply Secure Configurations to All System Components','System security parameters prevent misuse','System security parameters are configured to prevent misuse.','preventive','high'),
  ('pci-dss','2.2.7','Requirement 2: Apply Secure Configurations to All System Components','Non-console administrative access is encrypted','All non-console administrative access is encrypted using strong cryptography.','technical','high'),
  ('pci-dss','2.3.1','Requirement 2: Apply Secure Configurations to All System Components','Wireless vendor defaults are changed','For wireless environments connected to the CDE or transmitting account data, all wireless vendor defaults are changed at installation or confirmed to be secure, including default encryption keys, passwords, and SNMP community strings.','preventive','high'),
  ('pci-dss','2.3.2','Requirement 2: Apply Secure Configurations to All System Components','Wireless encryption keys are changed','For wireless environments connected to the CDE or transmitting account data, wireless encryption keys are changed whenever anyone with knowledge of the key leaves the company or role, or when a key is suspected of or known to be compromised.','preventive','medium'),

  -- Requirement 3: Protect Stored Account Data
  ('pci-dss','3.1.1','Requirement 3: Protect Stored Account Data','Security policies and procedures for Requirement 3 are documented','All security policies and operational procedures that are identified in Requirement 3 are documented, kept up to date, in use, and known to all affected parties.','governance','medium'),
  ('pci-dss','3.1.2','Requirement 3: Protect Stored Account Data','Roles and responsibilities for Requirement 3 are assigned','Roles and responsibilities for performing activities in Requirement 3 are documented, assigned, and understood.','governance','medium'),
